    });

    it('跳过空行与非法 JSON', async () => {
        const res = fakeResponse(['{"id":1}\n\nnot-json\n{"id":2}\n']);
        expect(await collect(parseNdjson(res))).toEqual([{ id: 1 }, { id: 2 }]);
    });
});

