import { ref, computed, onMounted } from 'vue';
import { useNuxtApp } from 'nuxt/app';
import { useThemeStore } from '@/stores/theme';
import { useMainStore } from '@/stores/main';

const { $backend } = useNuxtApp();
const { t } = useI18n();
const themeStore = useThemeStore();
const mainStore = useMainStore();

const themes = ref([]);
const installUrl = ref('');
const installing = ref(false);
const uploadFile = ref(null);
const uploading = ref(false);
const activating = ref('');
const deleting = ref('');

const displayThemes = computed(() => {
    const hasActiveCustomTheme = themes.value.some(t => t.active);
    const defaultItem = {
        _key: '__default__',
        _isDefault: true,
        name: t('theme.defaultTheme'),
        description: t('theme.defaultThemeDescription'),
        active: !hasActiveCustomTheme,
    };
    const customItems = themes.value.map(t => ({
        ...t,
        _key: t.name,
        _isDefault: false,
    }));

    if (hasActiveCustomTheme) {
        const activeTheme = customItems.find(t => t.active);
        const otherCustom = customItems.filter(t => !t.active);
        return [activeTheme, defaultItem, ...otherCustom];
    }
    return [defaultItem, ...customItems];
});

const snackbar = ref({ show: false, msg: '', color: 'success' });

function showMsg(msg, color = 'success') {
    snackbar.value = { show: true, msg, color };
}

async function fetchThemes() {
    const res = await $backend('/themes');
    if (res.err === 'ok') {
        themes.value = res.themes;
    }
}

async function installTheme() {
    installing.value = true;
    try {
        const res = await $backend('/themes/install', {
            method: 'POST',
            body: JSON.stringify({ download_url: installUrl.value }),
            headers: { 'Content-Type': 'application/json' },
        });
        if (res.err === 'ok') {
            showMsg(res.msg || '安装成功');
            installUrl.value = '';
            await fetchThemes();
            await themeStore.fetchActiveTheme();
        } else {
            showMsg(res.msg || '安装失败', 'error');
        }
    } finally {
        installing.value = false;
    }
}

async function uploadTheme() {
    if (!uploadFile.value) return;
    uploading.value = true;
    try {
        const formData = new FormData();
        formData.append('theme_file', uploadFile.value);
        const res = await $backend('/themes/install', {
            method: 'POST',
            body: formData,
        });
        if (res.err === 'ok') {
            showMsg(res.msg || '安装成功');
            uploadFile.value = null;
            await fetchThemes();
            await themeStore.fetchActiveTheme();
        } else {
            showMsg(res.msg || '安装失败', 'error');
        }
    } finally {
        uploading.value = false;
    }
}

async function activateTheme(key) {
    activating.value = key;
    try {
        let res;
        if (key === '__default__') {
            res = await themeStore.deactivate();
        } else {
            res = await themeStore.activate(key);
        }
        if (res.err === 'ok') {
            showMsg(res.msg || '已激活');
            await fetchThemes();
        } else {
            showMsg(res.msg || '激活失败', 'error');
        }
    } finally {
        activating.value = '';
    }
}

async function deleteTheme(name) {
    if (!confirm(t('theme.deleteConfirm'))) return;
    deleting.value = name;
    try {
        const res = await $backend(`/themes/${encodeURIComponent(name)}`, { method: 'DELETE' });
        if (res.err === 'ok') {
            showMsg(res.msg || '已删除');
            if (themeStore.activeTheme?.name === name) {
                themeStore.activeTheme = null;
            }
            await fetchThemes();
        } else {
            showMsg(res.msg || '删除失败', 'error');
        }
    } finally {
        deleting.value = '';
    }
}

onMounted(async () => {
