{"function":"() => {
  const cache = window.localStorage.getItem('talebook.activeTheme');
  const header = document.querySelector('.tb-theme-header');
  const drawer = document.querySelector('.tb-theme-hacker-news-compact .v-navigation-drawer');
  return {
    readyState: document.readyState,
    cacheName: cache ? JSON.parse(cache).name : null,
    headerClass: header?.className || null,
    activeStyle: document.querySelector('style[data-talebook-theme]')?.getAttribute('data-talebook-theme') || null,
    defaultHeaderVisible: Boolean(document.querySelector('header.v-app-bar:not(.tb-theme-header *)')),
    drawerWidth: drawer ? getComputedStyle(drawer).width : null,
    bodySample: document.body.innerText.slice(0, 120),
  };
}"}

arguments.function:
() => {
  const cache = window.localStorage.getItem('talebook.activeTheme');
  const header = document.querySelector('.tb-theme-header');
  const drawer = document.querySelector('.tb-theme-hacker-news-compact .v-navigation-drawer');
  return {
    readyState: document.readyState,
    cacheName: cache ? JSON.parse(cache).name : null,
    headerClass: header?.className || null,
    activeStyle: document.querySelector('style[data-talebook-theme]')?.getAttribute('data-talebook-theme') || null,
    defaultHeaderVisible: Boolean(document.querySelector('header.v-app-bar:not(.tb-theme-header *)')),
    drawerWidth: drawer ? getComputedStyle(drawer).width : null,
    bodySample: document.body.innerText.slice(0, 120),
  };
}

