async () => {
  await new Promise(resolve => setTimeout(resolve, 1500));
  const header = document.querySelector('.tb-theme-header');
  const drawer = document.querySelector('.tb-theme-cloudflare-radar .v-navigation-drawer');
  const activeItem = document.querySelector('.tb-theme-cloudflare-radar .v-list-item--active');
  const firstIcon = document.querySelector('.tb-theme-cloudflare-radar .v-list-item__prepend .v-icon');
  const mainContainer = document.querySelector('.v-main .v-container');
  const firstCard = Array.from(document.querySelectorAll('.v-main .v-card')).find(card => card.textContent.includes('主题管理')) || document.querySelector('.v-main .v-card');
  const style = el => el ? getComputedStyle(el) : null;
  const drawerStyle = style(drawer);
  const activeStyle = style(activeItem);
  const iconStyle = style(firstIcon);
  const containerStyle = style(mainContainer);
  const cardStyle = style(firstCard);
  const active = await fetch('/api/themes/active').then(r => r.json()).catch(e => ({ error: String(e) }));
  return {
    url: location.href,
    title: document.title,
    activeTheme: active.theme?.name || null,
    headerClass: header?.className || null,
    themeStyle: document.querySelector('style[data-talebook-theme]')?.getAttribute('data-talebook-theme') || null,
    appBackground: getComputedStyle(document.querySelector('.v-application')).backgroundColor,
    drawerWidth: drawerStyle?.width || null,
    activeBackground: activeStyle?.backgroundColor || null,
    iconColor: iconStyle?.color || null,
    containerPadding: containerStyle ? `${containerStyle.paddingTop} ${containerStyle.paddingRight}` : null,
    cardRadius: cardStyle?.borderRadius || null,
    cardBorder: cardStyle?.borderTopColor || null,
    bodyText: document.body.innerText.slice(0, 300),
  };
}

