async () => {
  await new Promise(resolve => setTimeout(resolve, 1500));
  const cards = Array.from(document.querySelectorAll('.theme-card')).map((el, index) => {
    const rect = el.getBoundingClientRect();
    return { index, h: Math.round(rect.height), w: Math.round(rect.width), top: Math.round(rect.top), left: Math.round(rect.left), text: el.innerText.split('\n')[0] };
  });
  const uploadButton = Array.from(document.querySelectorAll('button')).find(button => button.innerText.includes('上传主题包安装'));
  const uploadRect = uploadButton?.getBoundingClientRect();
  const headRect = document.querySelector('.theme-page-head')?.getBoundingClientRect();
  const cardText = document.querySelector('.v-card-text')?.innerText || '';
  const search = document.querySelector('.tb-theme-search, .search-wrapper');
  const header = document.querySelector('.tb-theme-appbar, .v-app-bar');
  const searchRect = search?.getBoundingClientRect();
  const headerRect = header?.getBoundingClientRect();
  return {
    href: location.href,
    uploadButton: uploadRect ? { text: uploadButton.innerText.trim(), left: Math.round(uploadRect.left), right: Math.round(uploadRect.right), top: Math.round(uploadRect.top) } : null,
    headRightGap: headRect && uploadRect ? Math.round(headRect.right - uploadRect.right) : null,
    hasUrlInput: Boolean(document.querySelector('input[name="download_url"]')) || cardText.includes('主题包下载地址') || cardText.includes('Theme package URL'),
    hasVisibleFileInput: Array.from(document.querySelectorAll('input[type="file"]')).some(input => getComputedStyle(input).display !== 'none'),
    cardCount: cards.length,
    cards,
    cardHeights: [...new Set(cards.map(card => card.h))],
    searchRightGap: headerRect && searchRect ? Math.round(headerRect.right - searchRect.right) : null,
    search: searchRect ? { left: Math.round(searchRect.left), right: Math.round(searchRect.right), width: Math.round(searchRect.width) } : null,
  };
}

