  await new Promise(resolve => setTimeout(resolve, 1800));
  const cards = Array.from(document.querySelectorAll('.theme-card-title')).map(el => el.textContent.trim());
  const drawer = document.querySelector('.tb-theme-drawer');
  const activeItem = document.querySelector('.tb-theme-drawer .v-list-item--active');
  const appbar = document.querySelector('.tb-theme-appbar');
  const s = el => {
    if (!el) return null;
    const cs = getComputedStyle(el);
    return { bg: cs.backgroundColor, color: cs.color, border: cs.borderColor };
  };
  return {
    href: location.href,
    bodyClasses: Array.from(document.body.classList).filter(c => c.startsWith('tb-current-builtin-theme')),
    headerClass: document.querySelector('.tb-theme-header')?.className || null,
    cards,
    drawer: s(drawer),
    activeItem: s(activeItem),
    appbar: s(appbar),
  };
}"}

