const ebooks = ref(null);

function do_upload() {
    loading.value = true;
    const data = new FormData();

    let file = null;
    if (ebooks.value) {
        file = Array.isArray(ebooks.value) ? ebooks.value[0] : ebooks.value;
    }

    if (file) {
        data.append('ebook', file, encodeURIComponent(file.name || 'upload.bin'));
    }

