payload.arguments:
{"function":"async () => {
  const activate = async (name) => {
    localStorage.removeItem('talebook.activeTheme');
    const rsp = await fetch('/api/themes/activate', {
      method: 'POST', credentials: 'include', headers: {'Content-Type':'application/json'}, body: JSON.stringify({name})
    }).then(r => r.json());
    if (rsp.theme) localStorage.setItem('talebook.activeTheme', JSON.stringify(rsp.theme));
    return rsp;
  };
  const rsp = await activate('cloudflare-radar');
  location.href = '/admin/themes?verify=button-colors-cloudflare';
  return rsp.err;
}"}

