payload.arguments:
{"function":"() => {
  const buttons = Array.from(document.querySelectorAll('.v-main .v-btn'));
  const activate = buttons.find((button) => button.textContent.trim() === '激活');
  const upload = buttons.find((button) => button.textContent.trim() === '上传主题包安装');
  const floating = document.querySelector('.upload-btn');
  const chip = document.querySelector('.theme-card--active .v-chip');
  const css = el => el ? getComputedStyle(el) : null;
  return {
    body: document.body.className,
    activateBg: css(activate)?.backgroundColor,
    activateColor: css(activate)?.color,
    uploadBg: css(upload)?.backgroundColor,
    uploadColor: css(upload)?.color,
    floatingBg: css(floating)?.backgroundColor,
    floatingColor: css(floating)?.color,
    chipBg: css(chip)?.backgroundColor,
    chipColor: css(chip)?.color,
  };
}"}

